    out = []
    for M in range(n - 1, maxE + 1):
        s = 0
        for p in range(M, maxE + 1):
            v = ans[p]
            if v:
                s += v * bigC[p][M]
        out.append(str(s % P))
    sys.stdout.write(" ".join(out) + "\n")


